SELECT ID as id, date, sentimentScore, sampleCount
FROM ${table}
WHERE date = #{date}
LIMIT 1

SELECT ID as id, date, sentimentScore, sampleCount
FROM ${table}
WHERE date >= #{fromDate}
ORDER BY date ASC, ID ASC

SELECT ID as id, date, sentimentScore, sampleCount
FROM ${table}
ORDER BY date ASC, ID ASC
